#!/bin/sh\n# Emoji Clock: prints a clock‑face emoji representing the hour.\n# If an argument is supplied, it is used as the hour (0‑23); otherwise the current hour is used.\n\nif [ -n \"$1\" ]; then\n  hour=$1\nelse\n  hour=$(date +%H)\nfi\n\n# Ensure hour is an integer between 0 and 23\nhour=$(printf \"%d\" \"$hour\" 2>/dev/null || echo 0)\n\n# Convert to 12‑hour format (0 or 12 -> 12)\nhour_mod=$(( hour % 12 ))\nif [ \"$hour_mod\" -eq 0 ]; then\n  hour_mod=12\nfi\n\ncase \"$hour_mod\" in\n  1) emoji=\"🕐\" ;;\n  2) emoji=\"🕑\" ;;\n  3) emoji=\"🕒\" ;;\n  4) emoji=\"🕓\" ;;\n  5) emoji=\"🕔\" ;;\n  6) emoji=\"🕕\" ;;\n  7) emoji=\"🕖\" ;;\n  8) emoji=\"🕗\" ;;\n  9) emoji=\"🕘\" ;;\n  10) emoji=\"🕙\" ;;\n  11) emoji=\"🕚\" ;;\n  12) emoji=\"🕛\" ;;\n  *) emoji=\"❓\" ;;\nesac\n\nprintf \"%s\n\" \"$emoji\"
